CREATE TABLE IF NOT EXISTS wallet_balances(user_id BIGINT UNSIGNED NOT NULL,currency VARCHAR(10) NOT NULL,balance DECIMAL(18,6) NOT NULL DEFAULT 0,PRIMARY KEY(user_id,currency),CONSTRAINT fk_wallet_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallet_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,currency VARCHAR(10) NOT NULL,amount DECIMAL(18,6) NOT NULL,balance_after DECIMAL(18,6) NOT NULL,reason VARCHAR(255) NOT NULL,reference_type VARCHAR(80) NULL,reference_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),CONSTRAINT fk_wallet_ledger_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO wallet_balances(user_id,currency,balance) SELECT id,CASE WHEN currency IN ('EUR','USD','GBP','RUB') THEN currency ELSE 'EUR' END,credits FROM users WHERE credits<>0 ON DUPLICATE KEY UPDATE balance=balance+VALUES(balance);
